const editorMachine = setup({
  types: {
    context: {} as { content: string },
    events: {} as
      | { type: 'EDIT' }
      | { type: 'REVIEW' }
      | { type: 'APPROVE' }
      | { type: 'SAVE' }
      | { type: 'ESCAPE' },
  },
  actions: {
    saveContent: () => {
      console.log('Saved');
    },
  },
}).createMachine({
  id: 'editor',
  initial: 'editing',
  states: {
    viewing: {
      on: {
        EDIT: 'editing',
      },
    },
    editing: {
      initial: 'draft',
      states: {
        draft: {
          on: {
            SAVE: { actions: 'saveContent' },
          },
        },
        reviewing: {
          on: {
            APPROVE: '#editor.approved',
          },
        },
      },
      on: {
        REVIEW: '.reviewing',
        ESCAPE: 'viewing',
      },
    },
    approved: {
      type: 'final',
    },
  },
});

