const playerMachine = setup({
  types: {
    context: {} as {
      buffered: number;
      currentTime: number;
    },
    events: {} as
      | { type: 'PLAY' }
      | { type: 'PAUSE' }
      | { type: 'BUFFER' }
      | { type: 'END' },
  },
}).createMachine({
  id: 'player',
  type: 'parallel',
  states: {
    transport: {
      initial: 'paused',
      states: {
        playing: {
          on: { PAUSE: 'paused' },
        },
        paused: {
          on: { PLAY: 'playing' },
        },
      },
    },
    buffering: {
      initial: 'ready',
      states: {
        ready: {
          on: { BUFFER: 'buffering' },
        },
        buffering: {
          on: { END: 'ready' },
        },
      },
    },
  },
});
